    /**
     * 歧义词上下文消歧：当 $keyword 命中 AMBIGUOUS 时，按 $contextText 中的上下文词判定归一品类的义项。
     * @param string $keyword      待消歧的关键词（如"苹果"）
     * @param string $contextText  用户原句 / 相邻语境文本
     * @return string 归一品类词（命中义项）或 ''（无歧义 / 上下文无法判定）
     */
    public static function disambiguate($keyword, $contextText)
    {
        if (!isset(self::AMBIGUOUS[$keyword])) {
            return '';
        }
        $text = mb_strtolower($contextText);
        $best = null;
        $bestScore = 0;
        foreach (self::AMBIGUOUS[$keyword] as $sense) {
            $score = 0;
            foreach ($sense['context'] as $ctx) {
                $ctxL = mb_strtolower($ctx);
                if ($ctxL !== '' && mb_strpos($text, $ctxL) !== false) {
                    $score++;
                }
            }
            // 命中数量相同时，priority 高者优先；否则命中数多者优先
            $weighted = $score * 10 + (isset($sense['priority']) ? intval($sense['priority']) : 0);
            if ($score > 0 && $weighted > $bestScore) {
                $bestScore = $weighted;
                $best = $sense['cat'];
            }
        }
        return $best === null ? '' : $best;
    }

    /**
     * 从完整用户消息中扫描歧义词并消歧（不依赖先抽关键词）。
     * 适合在意图分析最前置调用：若原句含"苹果/小米"等歧义词且上下文足以判定义项，
     * 直接返回归一品类词，避免后续 extractKeyword 把"苹果手机"截断为"苹果max蓝色"导致消歧失效。
     * @param string $text 用户原句
     * @return string 归一品类词（命中）或 ''（无歧义词 / 上下文无法判定）
     */
    public static function disambiguateFromMessage($text)
    {
        if ($text === '') {
            return '';
        }
        $textL = mb_strtolower($text);
        foreach (self::AMBIGUOUS as $word => $senses) {
            $wordL = mb_strtolower($word);
            if (mb_strpos($textL, $wordL) === false) {
                continue;
            }
            // 该歧义词出现在句中，按上下文判定义项
            $best = null;
            $bestScore = 0;
            foreach ($senses as $sense) {
                $score = 0;
                foreach ($sense['context'] as $ctx) {
                    $ctxL = mb_strtolower($ctx);
                    if ($ctxL !== '' && mb_strpos($textL, $ctxL) !== false) {
                        $score++;
                    }
                }
                $weighted = $score * 10 + (isset($sense['priority']) ? intval($sense['priority']) : 0);
                if ($score > 0 && $weighted > $bestScore) {
                    $bestScore = $weighted;
                    $best = $sense['cat'];
                }
            }
            if ($best !== null) {
                return $best;
            }
        }
        return '';
    }

