    /** 文档总数 */
    protected $n = 0;
    /** term => 出现该 term 的文档数 (DF) */
    protected $df = [];
    /** docId => [term => tf] */
    protected $docs = [];
    /** docId => 文档原始 term 集合（用于未命中时的宽松匹配） */
    protected $docTerms = [];
    /** 平均文档长度（term 数） */
    protected $avgdl = 0;
    /** BM25 参数 */
    protected $k1 = 1.5;
    protected $b = 0.75;

    /**
     * 用一批文档构建索引
     * @param array $docs [docId => text, ...]
     */
    public function build(array $docs)
    {
        $this->docs = [];
        $this->df = [];
        $this->docTerms = [];
        $this->n = 0;
        $totalLen = 0;

        foreach ($docs as $id => $text) {
            $terms = $this->tokenize((string)$text);
            if (empty($terms)) {
                continue;
            }
            $tf = [];
            foreach ($terms as $t) {
                if (isset(self::STOPWORDS[$t])) {
                    continue;
                }
                $tf[$t] = isset($tf[$t]) ? $tf[$t] + 1 : 1;
            }
            if (empty($tf)) {
                continue;
            }
            $this->docs[$id] = $tf;
            $this->docTerms[$id] = array_keys($tf);
            $totalLen += count($terms);
            $this->n++;
            foreach (array_keys($tf) as $t) {
                $this->df[$t] = isset($this->df[$t]) ? $this->df[$t] + 1 : 1;
            }
        }
        $this->avgdl = $this->n > 0 ? ($totalLen / $this->n) : 0;
        return $this;
    }

    /**
     * 对查询返回 [docId => bm25Score]，按分数降序的关联数组
     * @param string $query
     * @param array $allowedIds 限定候选（如已按 biz 过滤后的 docId 列表），空=全部
     * @param int $topK 返回前 K（0=全部）
     */
    public function search($query, array $allowedIds = [], $topK = 0)
    {
        $qTerms = $this->expandQuery($query);
        if (empty($qTerms)) {
            return [];
        }

        $scope = $this->docs;
        if (!empty($allowedIds)) {
            $set = array_flip($allowedIds);
            $scope = array_intersect_key($this->docs, $set);
        }

        $scores = [];
        foreach ($scope as $id => $tf) {
            $score = 0.0;
            $dl = array_sum($tf);
            foreach ($qTerms as $qt) {
                if (!isset($tf[$qt])) {
                    continue;
                }
                $df = $this->df[$qt] ?? 0;
                if ($df == 0) {
                    continue;
                }
                $idf = log(($this->n - $df + 0.5) / ($df + 0.5) + 1.0);
                $tfVal = $tf[$qt];
                $denom = $tfVal + $this->k1 * (1 - $this->b + $this->b * ($dl / ($this->avgdl ?: 1)));
                $score += $idf * ($tfVal * ($this->k1 + 1) / $denom);
            }
            if ($score > 0) {
                $scores[$id] = $score;
            }
        }

        arsort($scores);
        if ($topK > 0) {
            $scores = array_slice($scores, 0, $topK, true);
        }
        return $scores;
    }

    /**
     * 当前索引文档数（缓存校验用）
     */
    public function docCount()
    {
        return $this->n;
    }

    /**
     * 序列化内部状态（用于文件缓存，避免每次请求重建索引）
     * @return string
     */
    public function serialize()
    {
        return serialize([
            'n'        => $this->n,
            'df'       => $this->df,
            'docs'     => $this->docs,
            'docTerms' => $this->docTerms,
            'avgdl'    => $this->avgdl,
            'k1'       => $this->k1,
            'b'        => $this->b,
        ]);
    }

    /**
     * 从序列化状态恢复
     * @param string $data
     * @return static
     */
    public static function unserialize($data)
    {
        $s = @unserialize($data);
        if (!is_array($s)) {
            return null;
        }
        $obj = new static();
        $obj->n = $s['n'];
        $obj->df = $s['df'];
        $obj->docs = $s['docs'];
        $obj->docTerms = $s['docTerms'];
        $obj->avgdl = $s['avgdl'];
        $obj->k1 = $s['k1'];
        $obj->b = $s['b'];
        return $obj;
    }

    /**
     * 查询词扩展：原词 + unigram/bigram 变体 + 同义词
     */
    protected function expandQuery($query)
    {
        $text = $this->lower(trim($query));
        $terms = $this->tokenize($text);
        $out = [];
        foreach ($terms as $t) {
            if (isset(self::STOPWORDS[$t])) {
                continue;
            }
            $out[$t] = true;
        }
        // 同义词扩展
        foreach ($terms as $t) {
            if (isset(self::SYNONYMS[$t])) {
                foreach (self::SYNONYMS[$t] as $syn) {
                    foreach ($this->tokenize($syn) as $st) {
                        if (!isset(self::STOPWORDS[$st])) {
                            $out[$st] = true;
                        }
                    }
                }
            }
        }

        // 热门词扩展：把宽泛意图词铺开到细分品类，扩大召回面
        foreach ($terms as $t) {
            if (isset(self::HOTWORDS[$t])) {
                foreach (self::HOTWORDS[$t] as $hw) {
                    // 热门词关联的细分词，先按下标做同义词再展开 n-gram
                    $out['zh:' . $hw] = true;
                    foreach ($this->tokenize($hw) as $ht) {
                        if (!isset(self::STOPWORDS[$ht])) {
                            $out[$ht] = true;
                        }
                    }
                    // 细分词本身的同义词也一并带入
                    if (isset(self::SYNONYMS[$hw])) {
                        foreach (self::SYNONYMS[$hw] as $hsyn) {
                            foreach ($this->tokenize($hsyn) as $hst) {
                                if (!isset(self::STOPWORDS[$hst])) {
                                    $out[$hst] = true;
                                }
                            }
                        }
                    }
                }
            }
        }

        // 品牌扩展：用户输入品牌名，召回该品牌所有相关商品
        foreach ($terms as $t) {
            if (isset(self::BRANDS[$t])) {
                foreach (self::BRANDS[$t] as $brand) {
                    $out['zh:' . $brand] = true;
                    foreach ($this->tokenize($brand) as $bt) {
                        if (!isset(self::STOPWORDS[$bt])) {
                            $out[$bt] = true;
                        }
                    }
                }
            }
        }

        // 用途/场景扩展：按用途、场景、人群、季节搜时映射到品类
        foreach ($terms as $t) {
            if (isset(self::USAGE[$t])) {
                foreach (self::USAGE[$t] as $use) {
                    $out['zh:' . $use] = true;
                    foreach ($this->tokenize($use) as $ut) {
                        if (!isset(self::STOPWORDS[$ut])) {
                            $out[$ut] = true;
                        }
                    }
                    // 用途关联的细分词若也在同义词典中，带入其同义
                    if (isset(self::SYNONYMS[$use])) {
                        foreach (self::SYNONYMS[$use] as $usyn) {
                            foreach ($this->tokenize($usyn) as $ust) {
                                if (!isset(self::STOPWORDS[$ust])) {
                                    $out[$ust] = true;
                                }
                            }
                        }
                    }
                }
            }
        }

        // 属性/材质/功效扩展：用户用修饰词描述商品时映射到特征词
        foreach ($terms as $t) {
            if (isset(self::ATTRIBUTES[$t])) {
                foreach (self::ATTRIBUTES[$t] as $attr) {
                    $out['zh:' . $attr] = true;
                    foreach ($this->tokenize($attr) as $at) {
                        if (!isset(self::STOPWORDS[$at])) {
                            $out[$at] = true;
                        }
                    }
                }
            }
        }

        // 扩展词典：全品类×品牌矩阵 + 长短尾 + 口语 + 方言
        foreach ($terms as $t) {
            if (isset(self::EXTENDED[$t])) {
                foreach (self::EXTENDED[$t] as $ex) {
                    $out['zh:' . $ex] = true;
                    foreach ($this->tokenize($ex) as $et) {
                        if (!isset(self::STOPWORDS[$et])) {
                            $out[$et] = true;
                        }
                    }
                }
            }
        }
        // 跨平台电商语义词库扩展（独立缓存文件 data/EcomLexicon.php）
        // 采用"子串命中"而非精确 token 命中：热词/长尾词多为 3-4 字，
        // 经 n-gram 切分后不会作为整体 token 出现，按子串匹配才能触发扩展。
        $ecom = self::loadEcomLexicon();
        if (!empty($ecom)) {
            $text = $this->lower(trim($query));
            $hit = array();
            foreach (($ecom['synonyms'] ?? array()) as $k => $v) {
                if (strpos($text, $k) !== false) $hit['syn:' . $k] = $v;
            }
            foreach (($ecom['slang'] ?? array()) as $k => $v) {
                if (strpos($text, $k) !== false) $hit['syn:' . $k] = $v;
            }
            foreach (array_keys(self::$ecomHotFlat) as $w) {
                if (strpos($text, $w) !== false) $hit['hw:' . $w] = true;
            }
            foreach (($ecom['attributes'] ?? array()) as $k => $v) {
                if (strpos($text, $k) !== false) $hit['attr:' . $k] = $v;
            }
            foreach (($ecom['longtail'] ?? array()) as $w) {
                if (strpos($text, $w) !== false) $hit['lt:' . $w] = true;
            }
            foreach ($hit as $key => $payload) {
                if (strpos($key, 'syn:') === 0) {
                    foreach ($payload as $syn) {
                        foreach ($this->tokenize($syn) as $st) {
                            if (!isset(self::STOPWORDS[$st])) $out[$st] = true;
                        }
                    }
                } elseif (strpos($key, 'hw:') === 0) {
                    $w = substr($key, 3);
                    $out['zh:' . $w] = true;
                    foreach ($this->tokenize($w) as $ht) {
                        if (!isset(self::STOPWORDS[$ht])) $out[$ht] = true;
                    }
                } elseif (strpos($key, 'attr:') === 0) {
                    foreach ($payload as $attr) {
                        $out['zh:' . $attr] = true;
                        foreach ($this->tokenize($attr) as $at) {
                            if (!isset(self::STOPWORDS[$at])) $out[$at] = true;
                        }
                    }
                } elseif (strpos($key, 'lt:') === 0) {
                    $w = substr($key, 3);
                    $out['zh:' . $w] = true;
                    foreach ($this->tokenize($w) as $lt) {
                        if (!isset(self::STOPWORDS[$lt])) $out[$lt] = true;
                    }
                }
            }
        }

        return array_keys($out);
    }

    /**
     * 中文 n-gram 分词（unigram + bigram + trigram）
     * 与 HashingEmbedding v2 保持一致的切词逻辑，保证向量/BM25 同源。
     */
    public function tokenize($text)
    {
        $text = $this->lower(trim($text));
        if ($text === '') {
            return [];
        }
        $tokens = [];

        // 英文/数字词
        if (preg_match_all('/[a-z0-9]+/', $text, $m)) {
            foreach ($m[0] as $w) {
                $tokens[] = 'en:' . $w;
            }
        }

        // 中文 n-gram
        $zh = preg_replace('/[^\x{4e00}-\x{9fa5}]/u', '', $text);
        $len = $this->mbLen($zh);
        if ($len === 1) {
            $tokens[] = 'zh:' . $zh;
        } else {
            for ($i = 0; $i < $len; $i++) {
                $tokens[] = 'zh:' . $this->mbSub($zh, $i, 1);
                if ($i < $len - 1) {
                    $tokens[] = 'zh:' . $this->mbSub($zh, $i, 2);
                }
                if ($i < $len - 2) {
                    $tokens[] = 'zh:' . $this->mbSub($zh, $i, 3);
                }
            }
        }
        return $tokens;
    }

    protected function lower($s)
    {
        return function_exists('mb_strtolower') ? mb_strtolower($s, 'UTF-8') : strtolower($s);
    }

    protected function mbLen($s)
    {
        return function_exists('mb_strlen') ? mb_strlen($s, 'UTF-8') : preg_match_all('/[\x{4e00}-\x{9fa5}]/u', $s);
    }

    protected function mbSub($s, $start, $length)
    {
        if (function_exists('mb_substr')) {
            return mb_substr($s, $start, $length, 'UTF-8');
        }
        $chars = preg_split('//u', $s, -1, PREG_SPLIT_NO_EMPTY);
        return implode('', array_slice($chars, $start, $length));
    }
}
